import React from "react";
import { NavLink } from "react-router-dom";
import {
  AppsOutlined,
  AssessmentOutlined,
  DashboardOutlined,
  LogoutOutlined,
  ShowChartOutlined,
  ShoppingBagOutlined,
  WalletOutlined,
} from "@mui/icons-material";
import "./Menu.css";

const navigationItems = [
  { label: "Overview", to: "/", icon: DashboardOutlined, end: true },
  { label: "Orders", to: "/orders", icon: ShoppingBagOutlined },
  { label: "Holdings", to: "/holdings", icon: WalletOutlined },
  { label: "Positions", to: "/positions", icon: ShowChartOutlined },
  { label: "Funds", to: "/funds", icon: AssessmentOutlined },
  { label: "Apps", to: "/apps", icon: AppsOutlined },
];

const Menu = ({ user, onLogout }) => {
  const frontendUrl =
    process.env.REACT_APP_FRONTEND_URL || "http://localhost:3000";
  const initials = (user?.name || "User")
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();

  return (
    <div className="menu-container trading-menu">
      <NavLink
        className="trading-menu-brand"
        to="/"
        aria-label="Dashboard overview"
      >
        <span className="trading-menu-brand-mark" aria-hidden="true">Z</span>
        <span className="trading-menu-brand-name">ZERODHA</span>
      </NavLink>

      <nav className="menus trading-menu-navigation" aria-label="Dashboard">
        <ul>
          {navigationItems.map(({ label, to, icon: Icon, end }) => (
            <li key={to}>
              <NavLink
                to={to}
                end={end}
                className={({ isActive }) =>
                  `trading-menu-link${isActive ? " is-active" : ""}`
                }
              >
                <Icon className="trading-menu-icon" aria-hidden="true" />
                <span>{label}</span>
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>

      <div className="trading-menu-account">
        <a
          className="trading-menu-website"
          href={frontendUrl}
          aria-label="Open Zerodha website"
        >
          Website
        </a>
        <div className="trading-menu-user" title={user?.email}>
          <span className="trading-menu-avatar" aria-hidden="true">
            {initials}
          </span>
          <span className="trading-menu-user-details">
            <span className="trading-menu-user-name">{user?.name || "Account"}</span>
            <span className="trading-menu-user-email">{user?.email}</span>
          </span>
        </div>
        <button
          type="button"
          className="trading-menu-logout"
          onClick={onLogout}
          aria-label="Sign out"
          title="Sign out"
        >
          <LogoutOutlined aria-hidden="true" />
          <span>Sign out</span>
        </button>
      </div>
    </div>
  );
};

export default Menu;
